import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    url_pattern = r'https?://(?:[-\w.]|(?:%[\da-fA-F]{2}))+'
    urls = re.findall(url_pattern, myString)
    domains = set()
    for url in urls:
        parsed = urllib.parse.urlparse(url)
        domain = parsed.netloc
        if domain.startswith('www.'):
            domain = domain[4:]
        domains.add(domain)
    result = {}
    for domain in domains:
        try:
            response = requests.get(f'https://api.ipapi.com/{domain}?access_key={API_KEY}')
            if response.status_code == 200:
                result[domain] = response.json()
            else:
                result[domain] = None
        except:
            result[domain] = None
    return result

