import json
import smtplib
SMTP_SERVER = "smtp.gmail.com"
SMTP_PORT = 587
EMAIL_ADDRESS = "your.email@gmail.com"
EMAIL_PASSWORD = "your.password"
def task_func(input_data=None, smtp_server=SMTP_SERVER, smtp_port=SMTP_PORT, email_address=EMAIL_ADDRESS, email_password=EMAIL_PASSWORD, smtp=None):
    if input_data is None:
        return []
    try:
        data = json.loads(input_data)
    except json.JSONDecodeError:
        return []
    names = []
    recipients = []
    if isinstance(data, list):
        for item in data:
            if isinstance(item, dict):
                name = item.get('name', '')
                email = item.get('email', '')
                if name and email:
                    names.append(name)
                    recipients.append(f"{name} <{email}>")
    elif isinstance(data, dict):
        name = data.get('name', '')
        email = data.get('email', '')
        if name and email:
            names.append(name)
            recipients.append(f"{name} <{email}>")
    if not names:
        return []
    message = f"Subject: Extracted Names\n\n" + "\n".join(names)
    if smtp is None:
        server = smtplib.SMTP(smtp_server, smtp_port)
        server.starttls()
        server.login(email_address, email_password)
        server.sendmail(email_address, recipients, message)
        server.quit()
    else:
        smtp.sendmail(email_address, recipients, message)
    return names

