import json
import smtplib
SMTP_SERVER = "smtp.gmail.com"
SMTP_PORT = 587
EMAIL_ADDRESS = "your.email@gmail.com"
EMAIL_PASSWORD = "your.password"
def task_func(input_data=None, smtp_server=SMTP_SERVER, smtp_port=SMTP_PORT, email_address=EMAIL_ADDRESS, email_password=EMAIL_PASSWORD, smtp=None):
    try:
        data = json.loads(input_data) if isinstance(input_data, str) else input_data
    except (json.JSONDecodeError, TypeError):
        return []
    recipients = []
    if isinstance(data, list):
        for item in data:
            if isinstance(item, dict) and 'email' in item and 'name' in item:
                recipients.append((item['email'], item['name']))
    elif isinstance(data, dict):
        if 'email' in data and 'name' in data:
            recipients.append((data['email'], data['name']))
    if not recipients:
        return []
    names = [name for _, name in recipients]
    message = f"Subject: Extracted Names\n\n" + "\n".join(names)
    if smtp is None:
        server = smtplib.SMTP(smtp_server, smtp_port)
        server.starttls()
        server.login(email_address, email_password)
        for email, _ in recipients:
            server.sendmail(email_address, email, message)
        server.quit()
    else:
        for email, _ in recipients:
            smtp.sendmail(email_address, email, message)
    return names

import requests
import json
import pandas as pd
import seaborn as sns
HEADERS = {'accept': 'application/json'}
def task_func(url, parameters):
    try:
        response = requests.get(url, params=parameters, headers=HEADERS)
        response.raise_for_status()
        data = response.json()
    except Exception:
        raise Exception("Invalid URL, cannot access, or invalid data")
    if not data:
        raise Exception("Empty data")
    try:
        df = pd.DataFrame(data)
    except Exception:
        raise Exception("Invalid data format")
    if df.empty:
        raise Exception("Empty data")
    numeric_cols = df.select_dtypes(include=['number']).columns
    if len(numeric_cols) < 2:
        raise Exception("Not enough numerical columns for correlation")
    corr = df[numeric_cols].corr()
    ax = sns.heatmap(corr, annot=True, cmap='coolwarm')
    return df, ax

