import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    data = json.loads(json_str)
    def remove_none(obj):
        if isinstance(obj, dict):
            return {k: remove_none(v) for k, v in obj.items() if v is not None}
        elif isinstance(obj, list):
            return [remove_none(item) for item in obj if item is not None]
        else:
            return obj
    data = remove_none(data)
    email_pattern = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'
    def replace_emails(obj):
        if isinstance(obj, str):
            return re.sub(email_pattern, REPLACE_NONE, obj)
        elif isinstance(obj, dict):
            return {k: replace_emails(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [replace_emails(item) for item in obj]
        else:
            return obj
    data = replace_emails(data)
    def collect_values(obj):
        values = []
        if isinstance(obj, dict):
            for v in obj.values():
                values.extend(collect_values(v))
        elif isinstance(obj, list):
            for item in obj:
                values.extend(collect_values(item))
        else:
            values.append(obj)
        return values
    all_values = collect_values(data)
    value_counts = Counter(all_values)
    return {"data": data, "value_counts": value_counts}

import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return {"data": None, "value_counts": Counter()}
    def clean(obj):
        if isinstance(obj, dict):
            return {k: clean(v) for k, v in obj.items() if v is not None}
        elif isinstance(obj, list):
            return [clean(item) for item in obj if item is not None]
        elif isinstance(obj, str):
            if re.match(r'^[\w\.-]+@[\w\.-]+\.\w+$', obj):
                return REPLACE_NONE
            return obj
        else:
            return obj
    cleaned = clean(data)
    values = []
    def collect_values(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                collect_values(v)
        elif isinstance(obj, list):
            for item in obj:
                collect_values(item)
        else:
            values.append(obj)
    collect_values(cleaned)
    value_counts = Counter(values)
    return {"data": cleaned, "value_counts": value_counts}

