import json
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import pandas as pd
def task_func(json_data: str, key_path: list):
    data = json.loads(json_data)
    current = data
    for key in key_path:
        if not isinstance(current, dict) or key not in current:
            raise KeyError(f"Key '{key}' not found")
        current = current[key]
    if not isinstance(current, list):
        raise ValueError("No numeric data found")
    numeric_values = []
    for item in current:
        if isinstance(item, (int, float)):
            numeric_values.append(item)
        elif isinstance(item, str):
            item_stripped = item.strip()
            if item_stripped == "":
                raise ValueError("Data string is empty or corrupted")
            try:
                numeric_values.append(float(item_stripped))
            except ValueError:
                raise ValueError("Data string is empty or corrupted")
    if len(numeric_values) == 0:
        raise ValueError("No numeric data found")
    df = pd.DataFrame(numeric_values, columns=["values"])
    fig, ax = plt.subplots()
    sns.boxplot(data=df, y="values", ax=ax)
    return fig

