        try:
            values = [float(x) for x in current.split()]
        except ValueError:
            raise ValueError("Data string is empty or corrupted")
    elif isinstance(current, list):
        values = []
        for item in current:
            try:
                values.append(float(item))
            except (ValueError, TypeError):
                continue
    else:
        try:
            values = [float(current)]
        except (ValueError, TypeError):
            raise ValueError("No numeric data found")
    if len(values) == 0:
        raise ValueError("No numeric data found")
    fig, ax = plt.subplots()
    sns.boxplot(data=pd.Series(values), ax=ax)
    ax.set_title(f"Boxplot of data at path {key_path}")
    return fig
